	local _zfaa34030     = 0x02
	local _zfaa34031  = 0x03
	local _zfaa34032       = 0x04
	local _zfaa34033 = 0x05
	local _zfaa34034      = 0x10
	local _zfaa34035   = 0x11
	local _zfaa34036    = 0x12
	local _zfaa34037        = 0x13 
	local _zfaa34038  = 0x20
	local _zfaa34039  = 0x21
	local _zfaa34040   = 0x22
	local _zfaa34041   = 0x23
	local _zfaa34042   = 0x24
	local _zfaa34043        = 0x30
	local _zfaa34044        = 0x31
	local _zfaa34045        = 0x32
	local _zfaa34046        = 0x33
	local _zfaa34047        = 0x34
	local _zfaa34048        = 0x35
	local _zfaa34049       = 0x36
