	-- Function to initialize and run the VM with the obfuscated chunk
	function VM.load(raw_payload_json, override_key)
		local function _zfaa3407(c)
			if typeof(c) ~= "table" then
				-- serde serializes the unit variant `Nil` as the bare string
				-- "Nil"; user strings always arrive as {String=...} objects,
				-- so a bare "Nil" here is unambiguously a real nil.
				if c == "Nil" then
					return nil
				end
				return c
			end
			-- serde_json tags enum variants as single-key tables
			if c.Number ~= nil then
				return c.Number
			elseif c.String ~= nil then
				return c.String
			elseif c.Boolean ~= nil then
				return c.Boolean
			elseif c.Nil ~= nil then
				return nil
			else
				return c
			end
		end

		-- Phase 2: Deserialization
		-- NO LONGER REQUIRES, uses injected module
		local vm_chunk, err = JSON.decode(raw_payload_json)
		
		if not vm_chunk then
			error(_zfaa34021 and ("could not decode VM payload: " .. (err or "")) or "invalid payload", 0)
			return
		end

		-- Normalize constants encoded as tagged enum objects back into primitives.
		if vm_chunk.constants then
			local key_idx = vm_chunk.license_key_index
			for idx, c in ipairs(vm_chunk.constants) do
				local norm = _zfaa3407(c)
				-- Inject the caller's license key into the placeholder constant
				-- by index (no sentinel string anywhere in the engine).
				if override_key and key_idx ~= nil and (idx - 1) == key_idx then
					norm = override_key
				end
				vm_chunk.constants[idx] = norm
			end
		end

		-- Normalize each nested function proto's constant pool as well.
		if vm_chunk.protos then
			for _, proto in ipairs(vm_chunk.protos) do
				if proto.constants then
					for idx, c in ipairs(proto.constants) do
						proto.constants[idx] = _zfaa3407(c)
					end
				end
			end
		end
		
		-- Run the VM directly in the calling thread. We deliberately do NOT wrap
		-- execution in a manually-driven coroutine: the scripts we run routinely
		-- call yielding Roblox APIs (task.wait, Tween/RBXScriptSignal :Wait,
		-- HttpService:*Async, ...), and those yields MUST propagate to the real
		-- task scheduler. The old resume-loop intercepted every yield and treated
		-- the ones it didn't recognize as a "VM request", which crashed on any
		-- task.wait inside the guest script. Luau's pcall is yieldable, so the
		-- loader's outer pcall still catches real errors even across yields.
		vdbg("license OK, payload decoded -- running hub")
		local results = table.pack(VM.execute(vm_chunk))
		-- If this prints, the main chunk ran to the end. A silent failure that
		-- still reaches here is logic (a feature pcall ate an error -- look for the
		-- "guest error" line above), not the hub failing to load.
		vdbg("hub main chunk returned normally (" .. tostring(results.n) .. " value(s))")

		-- Surface return values (ModuleScript mode).
		if _zfaa34021 and results.n > 0 then
			print("Module returned:", table.unpack(results, 1, results.n))
		end
		return table.unpack(results, 1, results.n)
	end

	return VM
end

