    local FullLock = (function()
-- Phase 2 "full lock" client decoder. The payload ciphertext ships in the file;
-- the decryption key does NOT. This module asks the license server for the key
-- (sending the license key + hardware id + build id), and only a clean VALID
-- response carries it back. A wrong/absent key yields garbage, so the VM simply
-- fails -- nobody can fake "valid".
--
-- Keystream (must match the Rust builder byte-for-byte):
--   block_i   = SHA256( key_bytes .. u32_le(i) )     -- 32 bytes, i = 0,1,2,...
--   keystream = block_0 .. block_1 .. ...
--   plain[j]  = cipher[j] XOR keystream[j]
--
-- Wrapped as a factory that takes JSON (for request/response coding).

return function(JSON)
	local band, bor, bxor, bnot = bit32.band, bit32.bor, bit32.bxor, bit32.bnot
	local rrotate, rshift, lshift = bit32.rrotate, bit32.rshift, bit32.lshift
	local schar, sbyte, srep, ssub = string.char, string.byte, string.rep, string.sub
	local unpack = table.unpack or unpack

	local function add32(a, b)
		return (a + b) % 4294967296
	end

	local K256 = {
		0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
		0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
		0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
		0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
		0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
		0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
		0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
		0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
	}

	local function be32(x)
		return schar(band(rshift(x, 24), 255), band(rshift(x, 16), 255), band(rshift(x, 8), 255), band(x, 255))
	end

	-- SHA-256 over a byte string; returns the 32-byte raw digest.
	local function sha256(msg)
		local h0, h1, h2, h3, h4, h5, h6, h7 =
			0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19

		local len = #msg
		local bitlen = len * 8
		local zeros = (56 - (len + 1) % 64) % 64
		local hi = math.floor(bitlen / 4294967296)
		local lo = bitlen % 4294967296
		msg = msg .. "\128" .. srep("\0", zeros) .. be32(hi) .. be32(lo)

		local w = {}
		for chunk = 1, #msg, 64 do
			for t = 0, 15 do
				local p = chunk + t * 4
				local a, b, c, d = sbyte(msg, p, p + 3)
				w[t + 1] = bor(lshift(a, 24), lshift(b, 16), lshift(c, 8), d)
			end
			for t = 17, 64 do
				local x = w[t - 15]
				local y = w[t - 2]
				local s0 = bxor(rrotate(x, 7), rrotate(x, 18), rshift(x, 3))
				local s1 = bxor(rrotate(y, 17), rrotate(y, 19), rshift(y, 10))
				w[t] = add32(add32(w[t - 16], s0), add32(w[t - 7], s1))
			end

			local a, b, c, d, e, f, g, h = h0, h1, h2, h3, h4, h5, h6, h7
			for t = 1, 64 do
				local S1 = bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
				local ch = bxor(band(e, f), band(bnot(e), g))
				local temp1 = add32(add32(add32(h, S1), add32(ch, K256[t])), w[t])
				local S0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
				local maj = bxor(band(a, b), band(a, c), band(b, c))
				local temp2 = add32(S0, maj)
				h = g
				g = f
				f = e
				e = add32(d, temp1)
				d = c
				c = b
				b = a
				a = add32(temp1, temp2)
			end

			h0 = add32(h0, a)
			h1 = add32(h1, b)
			h2 = add32(h2, c)
			h3 = add32(h3, d)
			h4 = add32(h4, e)
			h5 = add32(h5, f)
			h6 = add32(h6, g)
			h7 = add32(h7, h)
		end

		return be32(h0) .. be32(h1) .. be32(h2) .. be32(h3) .. be32(h4) .. be32(h5) .. be32(h6) .. be32(h7)
	end

	local function le32(n)
		return schar(n % 256, math.floor(n / 256) % 256, math.floor(n / 65536) % 256, math.floor(n / 16777216) % 256)
	end

	-- XOR data against the SHA256-CTR keystream derived from key (both byte strings).
	local function keystream_xor(data, key)
		local out = {}
		local counter = 0
		local pos = 1
		local n = #data
		while pos <= n do
			local block = sha256(key .. le32(counter))
			local take = n - pos + 1
			if take > 32 then
				take = 32
			end
			local b = {}
			for k = 1, take do
				b[k] = bxor(sbyte(data, pos + k - 1), sbyte(block, k))
			end
			out[#out + 1] = schar(unpack(b, 1, take))
			pos = pos + take
			counter = counter + 1
		end
		return table.concat(out)
	end

	-- Standard base64 decode (ignores non-alphabet chars, including '=').
	local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local b64lut = {}
	for i = 1, 64 do
		b64lut[sbyte(B64, i)] = i - 1
	end
	local function b64decode(s)
		local out = {}
		local buf = {}
		local acc, bits = 0, 0
		for i = 1, #s do
			local v = b64lut[sbyte(s, i)]
			if v then
				acc = acc * 64 + v
				bits = bits + 6
				if bits >= 8 then
					bits = bits - 8
					buf[#buf + 1] = math.floor(acc / (2 ^ bits)) % 256
					acc = acc % (2 ^ bits)
					if #buf >= 4096 then
						out[#out + 1] = schar(unpack(buf, 1, #buf))
						buf = {}
					end
				end
			end
		end
		if #buf > 0 then
			out[#out + 1] = schar(unpack(buf, 1, #buf))
		end
		return table.concat(out)
	end

	local function hexdecode(s)
		local b = {}
		for i = 1, #s, 2 do
			b[#b + 1] = tonumber(ssub(s, i, i + 1), 16) or 0
		end
		return schar(unpack(b, 1, #b))
	end

	-- --- Roblox-side bits (device id + HTTP). Degrade to safe defaults. ---

	local function get_hwid()
		local hwid = "MOCK_HWID_NO_PLAYER"
		pcall(function()
			local Players = game:GetService("Players")
			if Players and Players.LocalPlayer then
				hwid = tostring(Players.LocalPlayer.UserId)
			end
		end)
		pcall(function() hwid = tostring(game:GetService("RbxAnalyticsService"):GetClientId()) end)
		pcall(function() if gethwid then hwid = tostring(gethwid()) end end)
		return hwid
	end

	-- The Roblox account running this. Reported alongside the device id purely so
	-- the licence owner can see WHO used a key (the device id is opaque). Empty
	-- strings when unavailable; the server treats them as optional.
	local function get_identity()
		local user_id, username = "", ""
		pcall(function()
			local Players = game:GetService("Players")
			local lp = Players and Players.LocalPlayer
			if lp then
				user_id = tostring(lp.UserId)
				username = tostring(lp.Name)
			end
		end)
		return user_id, username
	end

	local function http_post(url, body)
		-- Prefer the executor request APIs (work without the game HTTP toggle).
		-- Requesters live in getgenv() on most executors and sometimes in _G, so
		-- gather from both environments.
		local reqfns = {}
		local function add(v)
			if type(v) == "function" then
				reqfns[#reqfns + 1] = v
			end
		end
		local envs = {}
		local okg, g = pcall(function() return getgenv and getgenv() end)
		if okg and type(g) == "table" then
			envs[#envs + 1] = g
		end
		envs[#envs + 1] = _G
		for _, env in ipairs(envs) do
			local syn = rawget(env, "syn")
			if type(syn) == "table" then
				add(rawget(syn, "request"))
			end
			add(rawget(env, "http_request"))
			add(rawget(env, "request"))
		end
		for _, fn in ipairs(reqfns) do
			if type(fn) == "function" then
				local ok, resp = pcall(fn, {
					Url = url,
					Method = "POST",
					Headers = {
						["Content-Type"] = "application/json",
						-- Skip ngrok's free-tier browser-warning interstitial so the
						-- POST reaches the server as JSON. Ignored by other servers.
						["ngrok-skip-browser-warning"] = "true",
					},
					Body = body,
				})
				if ok and type(resp) == "table" and type(resp.Body) == "string" and resp.Body ~= "" then
					return resp.Body
				end
			end
		end
		-- Fall back to HttpService.
		local out
		pcall(function()
			local Http = game:GetService("HttpService")
			out = Http:PostAsync(url, body, Enum.HttpContentType.ApplicationJson)
		end)
		return out
	end

	-- The server has just answered VALID, and that answer is the only reason
	-- this build can run at all. Leave it where the script's own key window
	-- can find it (RvrseUI reads getgenv().LUAVM_LICENSE_OK), so the window
	-- does not ask the server the very same question again a second later.
	-- The unlock value is deliberately left out: it is the decrypt key, and
	-- nothing outside this closure ever needs to see it.
	local function leave_receipt(opts, decoded)
		local okg, g = pcall(function()
			return getgenv and getgenv()
		end)
		if not okg or type(g) ~= "table" then
			return
		end
		local at
		pcall(function()
			at = os.time()
		end)
		g.LUAVM_LICENSE_OK = {
			status = "VALID",
			key = opts.license_key or "",
			build_id = opts.build_id,
			tier = decoded.tier,
			expires_at = decoded.expires_at,
			expires_in_seconds = tonumber(decoded.expires_in_seconds),
			expires_in_days = tonumber(decoded.expires_in_days),
			at = at,
		}
	end

	-- loader(opts) -> (plaintext_json) on success, or (nil, reason).
	-- opts: { endpoint, build_id, cipher_b64, license_key }
	local function loader(opts)
		local user_id, username = get_identity()
		local reqbody = JSON.encode({
			key = opts.license_key or "",
			hardware_id = get_hwid(),
			build_id = opts.build_id,
			user_id = user_id,
			username = username,
		})
		local resp = http_post(opts.endpoint, reqbody)
		if type(resp) ~= "string" or resp == "" then
			return nil, "no server response"
		end
		local decoded = JSON.decode(resp)
		if type(decoded) ~= "table" then
			return nil, "bad server response"
		end
		if decoded.status ~= "VALID" or type(decoded.unlock) ~= "string" or decoded.unlock == "" then
			return nil, "license " .. tostring(decoded.status or "rejected")
		end
		leave_receipt(opts, decoded)
		local key = hexdecode(decoded.unlock)
		local cipher = b64decode(opts.cipher_b64)
		return keystream_xor(cipher, key)
	end

	return {
		load = loader,
		-- Exposed for self-tests (crypto only; no network).
		_crypto = {
			sha256 = sha256,
			keystream_xor = keystream_xor,
			b64decode = b64decode,
			hexdecode = hexdecode,
		},
	}
end

